head.script:
// 초기화 플래그 (페이지 로드 시 팝업 방지용)
var isInitializing = false;

scwin.onpageload = function() {


    // 초기화 시작
    isInitializing = true;

    // URL 파라미터에서 project_id 받기
    var projectId = $p.getParameter("project_id");



    if (projectId) {
        dm_search.set("projectId", projectId);
        // 프로젝트 멤버 목록 조회
        scwin.loadProjectUsers(projectId);
    } else {
        alert("프로젝트 ID가 필요합니다.");
        return;
    }

    // 그리드뷰 설정 및 이벤트 확인
    setTimeout(function() {


        if (grd_projectUsers && typeof grd_projectUsers.setSelection === 'function') {
            grd_projectUsers.setSelection(false);
        } else if (grd_projectUsers && typeof grd_projectUsers.clearSelection === 'function') {
            grd_projectUsers.clearSelection();
        }

        // 초기화 완료
        isInitializing = false;


        // 그리드뷰 선택 방지 설정
        if (grd_projectUsers) {
            // 그리드뷰 선택 기능 비활성화 (함수가 존재하지 않아 주석 처리)
            // grd_projectUsers.setUserSelection(false);

            // 모든 선택 해제
            try {
                grd_projectUsers.clearSelection();
            } catch (e) {
                // 선택 해제 실패 시 무시
            }
        }

        if (dl_projectUsers.getTotalRow() > 0) {

        }
    }, 500); // 시간을 좀 더 늘려서 그리드 완전 로딩 대기
};

// 프로젝트 멤버 목록 조회 (간단한 AJAX 방식)
scwin.loadProjectUsers = function(projectId) {


    try {
        // 간단한 jQuery AJAX 호출
        $.ajax({
            type: "POST",
            url: "/InsWebApp/ProjectAccessSettings.pwkjson",
            data: "projectId=" + encodeURIComponent(projectId),
            contentType: "application/x-www-form-urlencoded; charset=UTF-8",
            dataType: "json",
            success: function(data) {


                // 데이터리스트 초기화
                dl_projectUsers.removeAll();

                // 응답 데이터에서 프로젝트 사용자 목록 추출
                var projectUserList = data.projectUserListVo.projectUserVoList || [];


                // 데이터리스트에 데이터 추가 및 원본 데이터 저장
                originalData = []; // 초기화
                for (var i = 0; i < projectUserList.length; i++) {
                    var user = projectUserList[i];
                    var rowIndex = dl_projectUsers.insertRow();
                    // 기본 프로필 이미지 URL
                    var defaultProfileImage = "https://collabee.s3.ap-northeast-2.amazonaws.com/defaultUserImage.png";
                    var profileImageUrl = user.profileImageUrl && user.profileImageUrl.trim() !== "" ? user.profileImageUrl : defaultProfileImage;

                    dl_projectUsers.setCellData(rowIndex, "userId", user.userId || "");
                    dl_projectUsers.setCellData(rowIndex, "userName", user.userName || "");
                    dl_projectUsers.setCellData(rowIndex, "role", user.role || "");
                    dl_projectUsers.setCellData(rowIndex, "profileImageUrl", profileImageUrl);

                    // 원본 데이터 저장
                    originalData.push({
                        userId: user.userId || "",
                        userName: user.userName || "",
                        role: user.role || "",
                        profileImageUrl: profileImageUrl
                    });
                }



                // 프로필 이미지를 둥글게 만들기
                setTimeout(function() {
                    scwin.makeProfileImagesRound();
                }, 500);

                if (dl_projectUsers.getTotalRow() === 0) {

                } else {

                }
            },
            error: function(xhr, status, error) {

                alert("프로젝트 멤버 목록을 불러오는데 실패했습니다: " + error);
            }
        });

    } catch (e) {

        alert("프로젝트 멤버 목록을 불러오는데 오류가 발생했습니다: " + e.message);
    }
};

// 입력 필드 변경 이벤트 (검색 결과 초기화)
scwin.input_search_onkeyup = function(e) {
    // 검색 결과 및 메시지 초기화
    scwin.hideSearchMessage();
    dm_searchResult.set("found", false);
    dm_searchResult.set("isProjectMember", false);
    dm_searchResult.set("userId", "");
    dm_searchResult.set("userName", "");
    dm_searchResult.set("email", "");


};

// 검색 버튼 클릭
scwin.btn_search_onclick = function(e) {
    // 직접 input에서 값 가져오기
    var searchValue = input_search.getValue();
    var projectId = dm_search.get("projectId");

    if (!searchValue || searchValue.trim() === "") {
        scwin.showSearchMessage("사용자 ID를 입력해주세요.", true);
        return;
    }

    // 이메일 형식 검증
    var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailPattern.test(searchValue.trim())) {
        scwin.showSearchMessage("올바른 이메일 형식을 입력해주세요.", true);
        return;
    }

    // 사용자 검색 실행
    scwin.searchUser(searchValue.trim(), projectId);
};

// 사용자 검색 함수
scwin.searchUser = function(userId, projectId) {

    try {
        // 직접 AJAX 호출로 변경
        $.ajax({
            type: "GET",
            url: "/InsWebApp/ProjectUserSearch.pwkjson",
            data: {
                userId: userId,
                projectId: projectId
            },
            dataType: "json",
            success: function(data) {

                // 검색 결과를 데이터맵에 설정
                dm_searchResult.set("found", data.found || false);
                dm_searchResult.set("isProjectMember", data.isProjectMember || false);
                dm_searchResult.set("userId", data.userId || "");
                dm_searchResult.set("userName", data.userName || "");
                dm_searchResult.set("email", data.email || "");
                dm_searchResult.set("profileImageSrc", data.profileImageSrc || "");

                scwin.handleSearchResult(data);
            },
            error: function(xhr, status, error) {
                alert("사용자 검색에 실패했습니다.");
            }
        });
    } catch (e) {
        alert("사용자 검색 중 오류가 발생했습니다.");
    }
};





// 검색 메시지 표시 함수
scwin.showSearchMessage = function(message, isError) {
    try {
        output_searchMessage.setValue(message);

        // 스타일 적용
        var color = isError ? "#dc3545" : "#28a745"; // 빨간색 또는 초록색
        output_searchMessage.setStyle("color", color);
        output_searchMessage.setStyle("display", "block");

        // 3초 후 메시지 숨김
        //setTimeout(function() {
        //    scwin.hideSearchMessage();
        //}, 3000);
    } catch (e) {
    }
};

// 검색 메시지 숨김 함수
scwin.hideSearchMessage = function() {
    try {
        output_searchMessage.setStyle("display", "none");
        output_searchMessage.setValue("");
    } catch (e) {
    }
};

// 검색 결과 처리
scwin.handleSearchResult = function(result) {
    var found = result.found;
    var isProjectMember = result.isProjectMember;
    var email = result.email;
    var userName = result.userName;

    // 기존 메시지 숨김
    scwin.hideSearchMessage();



    if (!found) {
        scwin.showSearchMessage("해당 사용자 ID로 등록된 사용자를 찾을 수 없습니다.", true);
        // 검색 결과 데이터맵 초기화
        dm_searchResult.set("found", false);
        dm_searchResult.set("isProjectMember", false);
        dm_searchResult.set("userId", "");
        dm_searchResult.set("userName", "");
        dm_searchResult.set("email", "");
        return;
    }

    if (isProjectMember) {
        scwin.showSearchMessage("'" + userName + "' 사용자는 이미 프로젝트 멤버입니다.", true);
        // 검색 결과에서 멤버 상태 유지 (추가 버튼 클릭 시 경고용)
        dm_searchResult.set("found", true);
        dm_searchResult.set("isProjectMember", true);
        dm_searchResult.set("userId", result.userId || "");
        dm_searchResult.set("userName", userName);
        dm_searchResult.set("email", email);
        return;
    }

    // 사용자 추가 가능 상태
    scwin.showSearchMessage("사용자 '" + userName + "'을 프로젝트에 초대할 수 있습니다.", false);

    // 검색 결과 정상 상태로 설정
    dm_searchResult.set("found", true);
    dm_searchResult.set("isProjectMember", false);
    dm_searchResult.set("userId", result.userId || "");
    dm_searchResult.set("userName", userName);
    dm_searchResult.set("email", email);
};

// 실시간 멤버 여부 재확인 함수
scwin.recheckUserMembership = function(userId, projectId, callback) {
    try {
        $.ajax({
            type: "GET",
            url: "/InsWebApp/ProjectUserSearch.pwkjson",
            data: {
                userId: userId,
                projectId: projectId
            },
            dataType: "json",
            success: function(data) {

                callback(data.isProjectMember || false);
            },
            error: function(xhr, status, error) {

                // 오류 시 안전하게 false 반환
                callback(false);
            }
        });
    } catch (e) {

        callback(false);
    }
};

// 사용자 추가 버튼 클릭 (이메일 발송)
scwin.btn_addUser_onclick = function(e) {
    // 현재 검색된 사용자 정보 확인
    var searchValue = input_search.getValue();
    var projectId = dm_search.get("projectId");

    if (!searchValue || searchValue.trim() === "") {
        scwin.showSearchMessage("먼저 사용자를 검색해주세요.", true);
        return;
    }

    // 검색 결과에서 사용자 정보 확인
    var found = dm_searchResult.get("found");
    var isProjectMember = dm_searchResult.get("isProjectMember");
    var userName = dm_searchResult.get("userName");
    var resultEmail = dm_searchResult.get("email");



    // 현재 입력된 이메일과 검색 결과의 이메일이 일치하는지 확인
    if (resultEmail !== searchValue.trim()) {
        scwin.showSearchMessage("입력된 이메일과 검색 결과가 일치하지 않습니다. 다시 검색해주세요.", true);
        return;
    }

    if (!found) {
        scwin.showSearchMessage("검색된 사용자가 없습니다. 먼저 사용자를 검색해주세요.", true);
        return;
    }

    // 실시간으로 다시 한번 멤버 여부 확인

    scwin.recheckUserMembership(searchValue.trim(), projectId, function(isActualMember) {


        if (isActualMember) {
            scwin.showSearchMessage("'" + userName + "' 사용자는 이미 프로젝트 멤버입니다.", true);
            // 검색 결과도 업데이트
            dm_searchResult.set("isProjectMember", true);
            return;
        }

        // 이메일 발송 확인
        if (confirm("'" + userName + "' 사용자에게 프로젝트 초대 이메일을 발송하시겠습니까?")) {
            scwin.sendProjectInviteEmail(searchValue.trim(), projectId);
        }
    });
};

// 프로젝트 초대 이메일 발송 함수
scwin.sendProjectInviteEmail = function(userEmail, projectId) {
    try {
        // JSON 데이터로 전송
        $.ajax({
            type: "POST",
            url: "/InsWebApp/send/SendProjectInviteEmail.pwkjson",
            data: JSON.stringify({
                userId: userEmail,    // 초대받을 사용자 ID (이메일)
                email: userEmail,     // 초대받을 사용자 이메일 (실제 이메일 주소)
                projectId: projectId  // 프로젝트 ID
            }),
            contentType: "application/json; charset=UTF-8",
            dataType: "json",
            success: function(data) {
                if (data && data.success) {
                    alert("프로젝트 초대 이메일이 성공적으로 발송되었습니다.");

                    // 성공 시 입력값 초기화 및 UI 업데이트
                    input_search.setValue("");
                    scwin.hideSearchMessage();

                    // 검색 결과 데이터맵 초기화
                    dm_searchResult.set("found", false);
                    dm_searchResult.set("isProjectMember", false);
                    dm_searchResult.set("userId", "");
                    dm_searchResult.set("userName", "");
                    dm_searchResult.set("email", "");
                } else {
                    alert("이메일 발송에 실패했습니다: " + (data && data.message ? data.message : "알 수 없는 오류"));
                }
            },
            error: function(xhr, status, error) {
                alert("이메일 발송 중 오류가 발생했습니다: " + error);
            }
        });

    } catch (e) {
        alert("이메일 발송 중 예외가 발생했습니다: " + e.message);
    }
};

// 사용자 초대 함수 (기존 DB 추가용 - 현재는 사용하지 않음)
scwin.inviteUser = function(userId) {
    var projectId = dm_search.get("projectId");



    try {
        // 워크플로우 실행
        var option = {
            id: "wf_inviteUser",
            action: "action_inviteUser",
            success: function(data) {

                alert("사용자 초대가 완료되었습니다.\n\n사용자가 초대를 수락하면 프로젝트 멤버로 추가됩니다.");

                // 검색창 초기화
                dm_search.set("searchValue", "");

                // 멤버 목록 새로고침
                scwin.loadProjectUsers(projectId);
            },
            error: function(xhr, status, error) {

                alert("사용자 초대에 실패했습니다.");
            }
        };

        // 파라미터 설정
        wf_inviteUser.setParam("projectId", projectId);
        wf_inviteUser.setParam("userId", userId);

        // 워크플로우 실행
        $w.executeWorkflow(option);
    } catch (e) {

        alert("사용자 초대 중 오류가 발생했습니다.");
    }
};

// GridView 셀 변경 이벤트 핸들러 (역할 변경 처리)
scwin.grd_projectUsers_oncellchange = function(e) {
    // 초기화 중에는 처리하지 않음
    if (isInitializing) return;

    // 역할 컬럼이 변경된 경우에만 처리
    if (e.colID === "role") {
        var rowIndex = e.rowIndex;
        var userId = dl_projectUsers.getCellData(rowIndex, "userId");
        var userName = dl_projectUsers.getCellData(rowIndex, "userName");
        var newRole = e.newValue;
        var oldRole = e.oldValue;



        // 역할이 실제로 변경된 경우에만 처리
        if (newRole !== oldRole) {
            scwin.changeUserRole(userId, userName, newRole);
        }
    }
};

// 권한 변경 함수 (GridView에서 호출)
scwin.changeUserRole = function(userId, userName, newRole) {


    var projectId = dm_search.get("projectId");

    // 일단 권한 변경 기능은 추후 구현 예정
    alert("권한 변경 기능은 현재 개발 중입니다.\n" + userName + "의 역할을 " + 
          (newRole === "admin" ? "관리자" : "에디터") + "로 변경하려고 했습니다.");

    // 원래 상태로 되돌리기 위해 목록 새로고침
    scwin.loadProjectUsers(projectId);
};

// 동적 사용자 목록 렌더링
scwin.renderUserList = function() {


    var userListContainer = document.getElementById("grp_userDataList");
    if (!userListContainer) {

        return;
    }

    // 기존 사용자 목록 초기화
    userListContainer.innerHTML = "";

    // 데이터리스트에서 사용자 정보 가져오기
    var userCount = dl_projectUsers.getTotalRow();


    if (userCount === 0) {
        // 사용자가 없는 경우 메시지 표시
        var noDataDiv = document.createElement("div");
        noDataDiv.style.cssText = "padding:40px;text-align:center;color:#666666;font-size:16px;";
        noDataDiv.innerHTML = "프로젝트에 참여하는 멤버가 없습니다.";
        userListContainer.appendChild(noDataDiv);
        return;
    }

    // 각 사용자에 대해 HTML 생성
    for (var i = 0; i < userCount; i++) {
        var userId = dl_projectUsers.getCellData(i, "userId");
        var userName = dl_projectUsers.getCellData(i, "userName");
        var email = dl_projectUsers.getCellData(i, "email");
        var role = dl_projectUsers.getCellData(i, "role");

        // 사용자 행 생성
        var userRow = document.createElement("div");
        userRow.className = "user-row";
        userRow.style.cssText = "display:flex;padding:16px 24px;border-bottom:1px solid #e9ecef;align-items:center;";

        // 사용자명
        var nameDiv = document.createElement("div");
        nameDiv.style.cssText = "flex:1;text-align:center;font-size:16px;color:#333333;font-family:Inter,sans-serif;";
        nameDiv.textContent = userName;

        // 이메일
        var emailDiv = document.createElement("div");
        emailDiv.style.cssText = "flex:2;text-align:center;font-size:16px;color:#666666;font-family:Inter,sans-serif;";
        emailDiv.textContent = email;

        // 역할 선택
        var roleDiv = document.createElement("div");
        roleDiv.style.cssText = "flex:1;text-align:center;";

        var roleSelect = document.createElement("select");
        roleSelect.style.cssText = "width:100px;height:36px;border:1px solid #ddd;border-radius:6px;padding:0 8px;font-size:14px;font-family:Inter,sans-serif;";

        // 관리자 옵션
        var adminOption = document.createElement("option");
        adminOption.value = "admin";
        adminOption.textContent = "관리자";
        if (role === "admin") adminOption.selected = true;

        // 에디터 옵션
        var editorOption = document.createElement("option");
        editorOption.value = "editor";
        editorOption.textContent = "에디터";
        if (role === "editor") editorOption.selected = true;

        roleSelect.appendChild(adminOption);
        roleSelect.appendChild(editorOption);

        // 역할 변경 이벤트 리스너
        roleSelect.addEventListener("change", function(userId, userName) {
            return function(e) {
                var newRole = e.target.value;
                scwin.changeUserRole(userId, userName, newRole);
            };
        }(userId, userName));

        roleDiv.appendChild(roleSelect);

        // 행에 요소들 추가
        userRow.appendChild(nameDiv);
        userRow.appendChild(emailDiv);
        userRow.appendChild(roleDiv);

        userListContainer.appendChild(userRow);
    }


};

// 그리드뷰 클릭 이벤트 핸들러 - 선택 효과 제거
scwin.grd_projectUsers_oncellclick = function(e) {


    // 클릭 후 선택 효과 제거
    setTimeout(function() {
        if (grd_projectUsers && typeof grd_projectUsers.clearSelection === 'function') {
            grd_projectUsers.clearSelection();
        } else if (grd_projectUsers && typeof grd_projectUsers.setSelection === 'function') {
            grd_projectUsers.setSelection(false);
        }
    }, 1);
    return false;
};

// 그리드뷰 선택 이벤트 핸들러 (추가)
scwin.grd_projectUsers_onselect = function(e) {

};

// 그리드뷰 afterchange 이벤트 핸들러 (추가)
scwin.grd_projectUsers_onafterchange = function(e) {


    // oncellchange가 작동하지 않는 경우를 위한 대안
    if (e && e.colID === "role") {

        var rowIndex = e.rowIndex;
        var userId = dl_projectUsers.getCellData(rowIndex, "userId");
        var userName = dl_projectUsers.getCellData(rowIndex, "userName");
        var newRole = e.newValue;
        var oldRole = e.oldValue;

        // oncellchange와 동일한 로직 수행
        if (newRole !== oldRole && newRole && oldRole && !isInitializing) {
            var existingIndex = pendingChanges.findIndex(function(change) {
                return change.userId === userId;
            });

            if (existingIndex !== -1) {
                pendingChanges[existingIndex].newRole = newRole;
            } else {
                pendingChanges.push({
                    userId: userId,
                    userName: userName,
                    oldRole: oldRole,
                    newRole: newRole
                });
            }


            alert("역할 변경이 임시 저장되었습니다: " + userName + " (" + oldRole + " → " + newRole + ")");
        }
    }
};

// 직접 select 요소의 change 이벤트를 감지하는 함수 추가
scwin.attachSelectChangeEvents = function() {
    var attempts = 0;
    var maxAttempts = 10;

    function tryAttachEvents() {
        attempts++;

        // 다양한 셀렉터로 select 요소 찾기
        var selects = document.querySelectorAll('#grd_projectUsers select');
        var allSelects = document.querySelectorAll('select'); // 모든 select
        var gridContainer = document.querySelector('#grd_projectUsers');



        if (gridContainer) {

        }

        if (selects.length > 0) {
            selects.forEach(function(select, index) {


                // 기존 이벤트 리스너가 있는지 확인
                if (!select.hasAttribute('data-event-attached')) {
                    select.setAttribute('data-event-attached', 'true');

                    select.addEventListener('change', function(event) {


                        var newValue = event.target.value;
                        var rowElement = event.target.closest('tr');
                        var rowIndex = Array.from(rowElement.parentNode.children).indexOf(rowElement) - 1; // 헤더 제외

                        if (rowIndex >= 0) {
                            var userId = dl_projectUsers.getCellData(rowIndex, "userId");
                            var userName = dl_projectUsers.getCellData(rowIndex, "userName");
                            var oldValue = dl_projectUsers.getCellData(rowIndex, "role");



                            if (newValue !== oldValue && newValue && oldValue) {
                                // 데이터리스트 업데이트
                                dl_projectUsers.setCellData(rowIndex, "role", newValue);

                                // 변경사항 저장
                                var existingIndex = pendingChanges.findIndex(function(change) {
                                    return change.userId === userId;
                                });

                                if (existingIndex !== -1) {
                                    pendingChanges[existingIndex].newRole = newValue;
                                } else {
                                    pendingChanges.push({
                                        userId: userId,
                                        userName: userName,
                                        oldRole: oldValue,
                                        newRole: newValue
                                    });
                                }


                            }
                        }
                    });
                }
            });


        } else if (attempts < maxAttempts) {

            setTimeout(tryAttachEvents, 500 * attempts); // 점진적으로 대기 시간 증가
        } else {

        }
    }

    tryAttachEvents();
};

