// 변경사항 임시 저장용 배열
var pendingChanges = [];
// 원본 데이터 저장용 배열
var originalData = [];

// GridView 셀 변경 이벤트 핸들러 (웹스퀘어 네이티브 방식)
scwin.grd_projectUsers_oncellchange = function(e) {


    // 초기화 중에는 처리하지 않음
    if (isInitializing) {

        return;
    }



    // 역할 컬럼이 변경된 경우에만 처리
    if (e.colID === "role") {
        var rowIndex = e.rowIndex;
        var userId = dl_projectUsers.getCellData(rowIndex, "userId");
        var userName = dl_projectUsers.getCellData(rowIndex, "userName");
        var newRole = e.newValue;
        var oldRole = e.oldValue;



        // 역할이 실제로 변경된 경우에만 처리
        if (newRole !== oldRole && newRole && oldRole) {
            // 임시 변경사항에 추가 (기존 변경사항이 있으면 업데이트)
            var existingIndex = pendingChanges.findIndex(function(change) {
                return change.userId === userId;
            });

            if (existingIndex !== -1) {
                pendingChanges[existingIndex].newRole = newRole;

            } else {
                var newChange = {
                    userId: userId,
                    userName: userName,
                    oldRole: oldRole,
                    newRole: newRole
                };
                pendingChanges.push(newChange);

            }


            alert("역할 변경이 임시 저장되었습니다: " + userName + " (" + oldRole + " → " + newRole + ")");
        } else {

        }
    } else {

    }
};

// 현재 데이터와 원본 데이터를 비교하여 변경사항 감지
scwin.detectRoleChanges = function() {

    pendingChanges = []; // 기존 변경사항 초기화

    var userCount = dl_projectUsers.getTotalRow();


    for (var i = 0; i < userCount; i++) {
        var currentUserId = dl_projectUsers.getCellData(i, "userId");
        var currentUserName = dl_projectUsers.getCellData(i, "userName");
        var currentRole = dl_projectUsers.getCellData(i, "role");

        // 원본 데이터에서 같은 사용자 찾기
        var originalUser = originalData.find(function(user) {
            return user.userId === currentUserId;
        });

        if (originalUser && originalUser.role !== currentRole) {


            pendingChanges.push({
                userId: currentUserId,
                userName: currentUserName,
                oldRole: originalUser.role,
                newRole: currentRole
            });
        }
    }


    return pendingChanges;
};

// 저장 버튼 클릭 이벤트
scwin.btn_save_onclick = function(e) {


    // 자동 감지가 실패한 경우 수동 감지 시도
    if (pendingChanges.length === 0) {

        scwin.detectRoleChanges();
    }

    if (pendingChanges.length === 0) {
        alert("변경된 내용이 없습니다.");
        return;
    }

    var projectId = dm_search.get("projectId");

    // 관리자 수 검증
    var finalAdminCount = 0;
    var userCount = dl_projectUsers.getTotalRow();

    for (var i = 0; i < userCount; i++) {
        var userId = dl_projectUsers.getCellData(i, "userId");
        var currentRole = dl_projectUsers.getCellData(i, "role");

        // 변경사항이 있는지 확인
        var pendingChange = pendingChanges.find(function(change) {
            return change.userId === userId;
        });

        var finalRole = pendingChange ? pendingChange.newRole : currentRole;
        if (finalRole === "admin") {
            finalAdminCount++;
        }
    }

    if (finalAdminCount < 1) {
        alert("프로젝트에는 최소 1명의 관리자가 있어야 합니다.");
        return;
    }

    // 변경사항 확인 메시지
    var changeList = pendingChanges.map(function(change) {
        return change.userName + ": " + (change.oldRole === "admin" ? "관리자" : "에디터") + 
               " → " + (change.newRole === "admin" ? "관리자" : "에디터");
    }).join("\n");

    if (!confirm("다음 변경사항을 저장하시겠습니까?\n\n" + changeList)) {
        return;
    }

    // 순차적으로 저장
    scwin.saveRoleChanges(0);
};

// 역할 변경사항 순차 저장
scwin.saveRoleChanges = function(index) {
    if (index >= pendingChanges.length) {
        // 모든 변경사항 저장 완료
        alert("모든 변경사항이 저장되었습니다.");
        pendingChanges = []; // 임시 저장 목록 초기화
        scwin.loadProjectUsers(dm_search.get("projectId")); // 목록 새로고침
        return;
    }

    var change = pendingChanges[index];
    var projectId = dm_search.get("projectId");



    var requestData = "projectId=" + encodeURIComponent(projectId) + 
                      "&userId=" + encodeURIComponent(change.userId) + 
                      "&role=" + encodeURIComponent(change.newRole);



    // GET 방식으로 테스트 (URL 파라미터 사용)
    $.ajax({
        type: "GET",
        url: "/InsWebApp/updateProjectUserRole.pwkjson?" + requestData,
        contentType: "application/x-www-form-urlencoded; charset=UTF-8",
        dataType: "json",
        success: function(data) {


            if (data && data.success) {

                // 다음 변경사항 처리
                scwin.saveRoleChanges(index + 1);
            } else {

                alert("역할 변경에 실패했습니다: " + change.userName + "\n" + 
                      (data && data.message ? data.message : "알 수 없는 오류"));
                scwin.loadProjectUsers(projectId); // 원래 상태로 복원
            }
        },
        error: function(xhr, status, error) {


            alert("역할 변경 중 오류가 발생했습니다: " + change.userName + "\n" + error);
            scwin.loadProjectUsers(projectId); // 원래 상태로 복원
        }
    });
};

// 사용자 역할 변경 함수 (기존 함수는 유지하되 사용하지 않음)
scwin.changeUserRole = function(userId, userName, newRole) {
    var projectId = dm_search.get("projectId");

    // 관리자를 에디터로 바꿀 때 관리자 수 확인
    if (newRole === "editor") {
        var adminCount = 0;
        var userCount = dl_projectUsers.getTotalRow();

        for (var i = 0; i < userCount; i++) {
            var role = dl_projectUsers.getCellData(i, "role");
            if (role === "admin") {
                adminCount++;
            }
        }

        if (adminCount <= 1) {
            alert("프로젝트에는 최소 1명의 관리자가 있어야 합니다.");
            scwin.loadProjectUsers(projectId); // 원래 상태로 복원
            return;
        }
    }

    // 서버에 역할 변경 요청
    $.ajax({
        type: "POST",
        url: "/InsWebApp/updateProjectUserRole.pwkjson",
        data: {
            projectId: projectId,
            userId: userId,
            role: newRole
        },
        contentType: "application/x-www-form-urlencoded; charset=UTF-8",
        dataType: "json",
        success: function(data) {
            if (data && data.success) {
                alert(userName + "의 역할이 " + (newRole === "admin" ? "관리자" : "에디터") + "로 변경되었습니다.");
                scwin.loadProjectUsers(projectId); // 목록 새로고침
            } else {
                alert("역할 변경에 실패했습니다: " + (data && data.message ? data.message : "알 수 없는 오류"));
                scwin.loadProjectUsers(projectId); // 원래 상태로 복원
            }
        },
        error: function(xhr, status, error) {
            alert("역할 변경 중 오류가 발생했습니다: " + error);
            scwin.loadProjectUsers(projectId); // 원래 상태로 복원
        }
    });
};

// 그리드뷰 셀 클릭 이벤트 (선택 방지)
scwin.grd_projectUsers_oncellclick = function(e) {
    // 선택 방지
    try {
        // 선택 해제
        grd_projectUsers.clearSelection();

        // 포커스 해제
        if (grd_projectUsers.setFocusedCell) {
            grd_projectUsers.setFocusedCell(-1, -1);
        }
    } catch (ex) {
        // 오류 시 무시
    }

    // 역할 컬럼 클릭 시에만 처리 (select 박스는 정상 작동하도록)
    if (e.colID === "role") {
        // select 박스는 정상 작동하도록 이벤트 전파 허용
        return true;
    }

    return false;
};

// 그리드뷰 선택 이벤트 (선택 방지)
scwin.grd_projectUsers_onselect = function(e) {
    // 항상 선택 방지
    try {
        // 선택 해제
        setTimeout(function() {
            grd_projectUsers.clearSelection();
        }, 1);
    } catch (ex) {
        // 오류 시 무시
    }

    // 선택 방지
    return false;
};

// 그리드뷰 after change 이벤트 (선택 해제)
scwin.grd_projectUsers_onafterchange = function(e) {
    // 변경 후 선택 해제
    try {
        setTimeout(function() {
            grd_projectUsers.clearSelection();
        }, 1);
    } catch (ex) {
        // 오류 시 무시
    }
};

// 프로필 이미지를 둥글게 만드는 함수
scwin.makeProfileImagesRound = function() {
    try {
        // 그리드뷰 내의 모든 이미지 찾기
        var gridElement = document.getElementById('grd_projectUsers');
        if (gridElement) {
            var images = gridElement.querySelectorAll('img');
            for (var i = 0; i < images.length; i++) {
                var img = images[i];
                img.style.borderRadius = '50%';
                img.style.objectFit = 'cover';
                img.style.width = '40px';
                img.style.height = '40px';
            }

            // 이미지 컨테이너도 둥글게
            var cells = gridElement.querySelectorAll('td[columnid="profileImageUrl"], .w2grid_cell[columnid="profileImageUrl"]');
            for (var j = 0; j < cells.length; j++) {
                cells[j].style.borderRadius = '50%';
                cells[j].style.overflow = 'hidden';
            }
        }
    } catch (e) {
        console.log('프로필 이미지 둥글게 만들기 실패:', e);
    }
};
